changeSet.sql:
CREATE TABLE rental_positions (
    id UUID PRIMARY KEY,
    rental_id UUID NOT NULL,
    vehicle_id UUID,
    latitude DOUBLE PRECISION NOT NULL,
    longitude DOUBLE PRECISION NOT NULL,
    location GEOGRAPHY(POINT,4326),
    recorded_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    source VARCHAR(16)
);
CREATE INDEX idx_rental_positions_rental_recorded ON rental_positions(rental_id, recorded_at);
CREATE INDEX idx_rental_positions_geo ON rental_positions USING GIST(location);
